#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<long long> A(N);
    for (int i = 0; i < N; i++) cin >> A[i];

    const long long INF = (1LL << 60);

    vector<long long> left(N, INF), right(N, INF), ans(N);

    long long cur = INF;
    for (int i = 0; i < N; i++) {
        if (A[i] != -1) cur = min(cur, A[i] - i);
        if (cur != INF) left[i] = cur + i;
    }

    cur = INF;
    for (int i = N - 1; i >= 0; i--) {
        if (A[i] != -1) cur = min(cur, A[i] + i);
        if (cur != INF) right[i] = cur - i;
    }

    for (int i = 0; i < N; i++) {
        ans[i] = min(left[i], right[i]);
    }

    for (int i = 0; i < N; i++) {
        if (i) cout << ' ';
        cout << ans[i];
    }
    cout << '\n';

    return 0;
}
